    }
  } catch (err) {
    debugLog("Skills dir doesn't exist", err);
  }

  // Check agents.md
  const agentsMd: SetupStatus["agentsMd"] = {
    exists: false,
    status: "missing",
  };

  try {
    await fs.access(agentsMdPath);
    agentsMd.exists = true;

    try {
      const hashContent = await fs.readFile(hashPath, "utf-8");
